*{box-sizing:border-box} :root{font-family:'DM Sans',sans-serif;color:#142d30;font-synthesis:none}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#cbe9ef}body{touch-action:none}button{font:inherit}#game-shell{position:relative;width:100%;height:100dvh;min-height:520px;overflow:hidden;background:#cbe9ef;isolation:isolate}#scene{position:absolute;inset:0;z-index:-2}#scene canvas{width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;z-index:-1;background:linear-gradient(180deg,rgba(244,251,246,.55),transparent 25%,transparent 72%,rgba(10,30,31,.18)),linear-gradient(90deg,rgba(23,47,45,.1),transparent 20%,transparent 80%,rgba(23,47,45,.1)}
.topbar{height:74px;padding:0 clamp(20px,4vw,58px);display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(255,255,255,.55);background:rgba(248,251,242,.5);backdrop-filter:blur(12px);position:absolute;left:0;right:0;top:0}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:#183335}.brand-mark{width:36px;height:36px;border-radius:11px;background:#d83e32;color:#fff;display:grid;place-items:center;font:700 12px 'Space Grotesk';letter-spacing:-.5px;box-shadow:0 4px 10px #9a3e3244}.brand-name{font:700 12px 'Space Grotesk';letter-spacing:1.2px}.brand-name b{color:#d84638}.route-pill{display:flex;align-items:center;gap:10px;padding:9px 15px;border:1px solid #fff9;border-radius:30px;background:#ffffff80;color:#425853;font-size:9px;font-weight:800;letter-spacing:1.2px}.route-pill i{font-style:normal;color:#a6b1a7}.route-dot{width:7px;height:7px;background:#72a756;border-radius:50%;box-shadow:0 0 0 3px #72a75627}.icon-btn,.pause-btn{border:1px solid #ffffffb8;background:#ffffff88;color:#274446;border-radius:12px;width:38px;height:38px;cursor:pointer;font-size:17px}.icon-btn{font-weight:bold}
.dashboard{position:absolute;top:94px;left:clamp(20px,4vw,58px);display:flex;gap:9px;align-items:stretch}.metric{height:75px;border:1px solid #ffffffba;background:rgba(251,253,247,.8);backdrop-filter:blur(12px);border-radius:13px;padding:11px 15px;box-shadow:0 6px 22px #27413c10}.speed-metric{width:148px}.distance-metric{width:205px}.score-metric{width:154px}.metric-label{font-size:8px;letter-spacing:1.4px;font-weight:800;color:#71827a;display:flex;gap:6px;align-items:center}.tiny-icon{font-size:12px;color:#d64a3c}.speed-line,.distance-line,.score-line{display:flex;align-items:baseline;gap:6px;margin-top:1px}.speed-line strong,.distance-line strong,.score-line strong{font:700 24px 'Space Grotesk';letter-spacing:-1px;color:#193436}.speed-line span,.distance-line span,.score-line span{font-size:8px;font-weight:800;color:#84918a;letter-spacing:1px}.speed-track,.route-progress{height:3px;background:#e1e9df;border-radius:5px;margin-top:4px;overflow:hidden}.speed-track i,.route-progress i{display:block;width:0;height:100%;background:#db4939;border-radius:5px;transition:width .2s}.distance-line strong{font-size:20px}.route-progress{margin-top:5px}.route-progress i{width:0;background:#80a85c}.destination{display:flex;justify-content:space-between;margin-top:4px;font-size:6px;font-weight:800;letter-spacing:.7px;color:#91a096}.destination b{color:#47624a;margin-left:4px}.score-line strong{font-size:21px}.score-caption{font-size:6px;color:#90a097;letter-spacing:1px;font-weight:700;margin-top:2px}.gear-badge{position:absolute;right:clamp(20px,4vw,58px);top:94px;border:1px solid #ffffffb8;background:#ffffffbb;border-radius:11px;padding:9px 12px;display:flex;align-items:center;gap:7px;font:700 13px 'Space Grotesk';box-shadow:0 6px 22px #27413c10}.gear-badge small{font:700 7px 'DM Sans';letter-spacing:1px;color:#87968a}.gear-dot{width:6px;height:6px;background:#83aa5b;border-radius:50%}.hint{position:absolute;right:clamp(20px,4vw,58px);top:150px;padding:9px 12px;border-radius:8px;background:#193b35bd;color:#f5f5e5;font-size:8px;font-weight:800;letter-spacing:1px;opacity:.82}.hint span{color:#f2a645;font-size:13px;vertical-align:-1px;margin-right:5px}.toast{position:absolute;top:47%;left:50%;transform:translate(-50%,-50%);padding:10px 18px;background:#193b35e8;color:#fff4db;border-radius:30px;font-size:11px;font-weight:800;letter-spacing:1px;opacity:0;transition:opacity .2s;pointer-events:none}.toast.show{opacity:1}
.bottom-note{position:absolute;bottom:22px;left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:9px;color:#f9fff0;text-shadow:0 1px 5px #1a3c37;font-size:8px;letter-spacing:1.5px;font-weight:700;white-space:nowrap}.bottom-note b{font-size:7px;color:#f6cb74}.sun-icon{font-size:13px;color:#f6c95f}.bottom-divider{height:12px;width:1px;background:#fff8;margin:0 2px}.pause-wrap{position:absolute;right:clamp(20px,4vw,58px);bottom:17px}.pause-btn{background:#ffffffa8;width:33px;height:33px;font-size:12px}
.modal-layer{position:absolute;inset:0;z-index:4;display:flex;align-items:center;justify-content:flex-start;padding:95px clamp(28px,10.8vw,156px) 55px;background:linear-gradient(90deg,rgba(234,244,229,.75),rgba(234,244,229,.36) 43%,transparent 76%);transition:opacity .35s,visibility .35s}.modal-layer.hidden{opacity:0;visibility:hidden;pointer-events:none}.welcome-card{width:min(420px,100%);padding:30px 32px 25px;border:1px solid #fff;background:rgba(249,250,242,.9);backdrop-filter:blur(18px);border-radius:21px;box-shadow:0 23px 65px #27473825}.eyebrow{display:flex;align-items:center;gap:8px;color:#79877a;font-size:8px;font-weight:800;letter-spacing:1.5px}.eyebrow span{width:7px;height:7px;border-radius:50%;background:#8caa63;box-shadow:0 0 0 4px #8caa6322}.welcome-card h1,.welcome-card h2{font:700 clamp(38px,4vw,52px)/.98 'Space Grotesk';letter-spacing:-2.8px;color:#173837;margin:20px 0 10px}.welcome-card h1 em,.welcome-card h2 em{font-style:normal;color:#d94a3b}.welcome-copy{font-size:12px;color:#74817a;margin:0 0 20px}.trip-card{height:62px;border-radius:12px;background:#eff2e8;display:flex;align-items:center;padding:0 12px;gap:11px;margin-bottom:12px}.trip-icon{height:36px;width:36px;border-radius:10px;background:#dfe8d2;color:#638246;display:grid;place-items:center;font-size:24px}.trip-card>div:nth-child(2){display:flex;flex-direction:column;gap:4px}.trip-card b{font-size:10px;color:#30483e}.trip-card span{font-size:8px;color:#829086}.trip-arrow{margin-left:auto;color:#7a9561;font-size:17px}.start-btn{width:100%;height:49px;display:flex;align-items:center;justify-content:space-between;padding:0 16px 0 19px;border:0;border-radius:11px;background:#d94a3b;color:white;cursor:pointer;box-shadow:0 7px 15px #d94a3b32;transition:transform .15s,background .15s}.start-btn:hover{background:#c93c30;transform:translateY(-1px)}.start-btn span{font-size:9px;font-weight:800;letter-spacing:1.4px}.start-btn b{font:500 20px 'Space Grotesk'}.controls-note{display:flex;align-items:center;justify-content:center;gap:7px;margin-top:17px;color:#8b968b;font-size:7px;font-weight:800;letter-spacing:.8px}.controls-note span{font-size:11px;color:#638246}.controls-note i{font-style:normal;color:#c3cabe}.modal-foot{position:absolute;left:50%;bottom:23px;transform:translateX(-50%);font-size:7px;letter-spacing:2px;font-weight:800;color:#75877a;white-space:nowrap}.modal-foot span{color:#d94a3b;margin-left:5px}.result-card{width:min(380px,100%)}.result-card h2{font-size:46px}.red-dot{background:#d94a3b!important;box-shadow:0 0 0 4px #d94a3b22!important}.result-stats{display:flex;gap:12px;margin:20px 0}.result-stats div{flex:1;background:#eff2e8;border-radius:11px;padding:12px}.result-stats b,.result-stats span{display:block}.result-stats b{font:700 16px 'Space Grotesk';color:#25413b}.result-stats span{font-size:7px;letter-spacing:1px;color:#849188;margin-top:4px;font-weight:800}
.mobile-controls{display:none;position:absolute;left:20px;right:20px;bottom:52px;align-items:flex-end;justify-content:space-between;z-index:2;pointer-events:none}.steer-controls,.pedal-controls{display:flex;gap:9px;pointer-events:auto}.mobile-controls button{border:1px solid #fff9;background:#f9fbf0d9;color:#28433c;backdrop-filter:blur(8px);box-shadow:0 5px 16px #16352c25;touch-action:none;user-select:none;-webkit-user-select:none}.steer-controls button{width:54px;height:54px;border-radius:17px;font:400 35px 'DM Sans';line-height:1}.pedal-controls button{width:58px;height:68px;border-radius:15px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px}.pedal-controls button span{font-size:16px}.pedal-controls small{font-size:7px;letter-spacing:1px;font-weight:800}.pedal-controls .gas{background:#d94a3b;color:white;border-color:#fff8}.pedal-controls .brake{background:#f8f6e8df}.mobile-controls button.active{transform:translateY(2px);filter:brightness(.92)}
@media(max-width:700px){#game-shell{min-height:450px}.topbar{height:59px;padding:0 16px}.brand-mark{width:32px;height:32px}.brand-name{font-size:10px}.route-pill{padding:8px 10px;gap:6px;font-size:7px;letter-spacing:.6px}.route-pill span:nth-last-child(1){display:none}.route-pill i{display:none}.icon-btn{height:34px;width:34px}.dashboard{top:72px;left:14px;gap:5px}.metric{height:66px;padding:9px 10px;border-radius:10px}.speed-metric{width:106px}.distance-metric{width:133px}.score-metric{width:103px}.metric-label{font-size:7px;letter-spacing:.8px}.speed-line strong{font-size:20px}.speed-line span,.distance-line span,.score-line span{font-size:7px}.distance-line strong{font-size:18px}.score-line strong{font-size:17px}.score-caption{font-size:5px}.destination{font-size:5px;letter-spacing:.3px}.gear-badge{top:151px;right:14px;padding:7px 9px}.hint{top:197px;right:14px;font-size:7px;padding:7px}.modal-layer{align-items:flex-end;justify-content:center;padding:0 16px 110px;background:linear-gradient(180deg,transparent 15%,rgba(231,241,226,.2) 32%,rgba(231,241,226,.82) 59%,rgba(231,241,226,.88))}.welcome-card{width:min(390px,100%);padding:21px 22px 18px;border-radius:18px}.welcome-card h1{font-size:42px;margin:13px 0 7px}.welcome-copy{font-size:11px;margin-bottom:14px}.trip-card{height:55px;margin-bottom:9px}.start-btn{height:46px}.controls-note{margin-top:12px}.modal-foot{bottom:15px;font-size:6px}.mobile-controls{display:flex;bottom:50px;left:14px;right:14px}.bottom-note{bottom:14px;font-size:6px;letter-spacing:.9px}.bottom-note b{font-size:6px}.pause-wrap{right:14px;bottom:11px}.pause-btn{width:29px;height:29px}.result-card{margin-bottom:20px}.result-card h2{font-size:40px}}
@media(max-height:650px) and (min-width:701px){.modal-layer{padding-top:75px;padding-bottom:35px}.welcome-card{padding:23px 27px 19px}.welcome-card h1{font-size:43px;margin:13px 0 7px}.welcome-copy{margin-bottom:13px}.trip-card{height:55px}.controls-note{margin-top:11px}.modal-foot{bottom:12px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.164.1/build/three.module.js';

const mount = document.querySelector('#scene');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0xc9e7ed);
scene.fog = new THREE.Fog(0xc9e7ed, 52, 205);
const camera = new THREE.PerspectiveCamera(54, innerWidth / innerHeight, .1, 350);
camera.position.set(0, 7.2, 13.5);
const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio || 1, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.18;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
mount.appendChild(renderer.domElement);

scene.add(new THREE.HemisphereLight(0xe9f9ff, 0x7d8c55, 2.1));
const sun = new THREE.DirectionalLight(0xfff1d0, 2.8);
sun.position.set(-18, 30, 16); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -24; sun.shadow.camera.right = 24; sun.shadow.camera.top = 35; sun.shadow.camera.bottom = -35;
scene.add(sun);
const fill = new THREE.DirectionalLight(0xc7e8ff, .65); fill.position.set(12, 9, -18); scene.add(fill);

const mat = (color, roughness = .82, metalness = 0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const mats = {
  grass: mat(0x91aa65), road: mat(0x424a48), shoulder: mat(0x777e70), line: mat(0xe9e5d1),
  busRed: mat(0xd94a3b, .45), busGreen: mat(0x347d50, .4), cream: mat(0xf1dfb2, .5), black: mat(0x172b2d, .7),
  glass: new THREE.MeshStandardMaterial({ color: 0x9dcbd0, roughness: .2, metalness: .1, transparent: true, opacity: .84 }), tire: mat(0x202323, .95), hub: mat(0xb9b8a9, .4, .45),
  tree: mat(0x416e49), leaf2: mat(0x6d914e), trunk: mat(0x77583b), hut: mat(0xc79c65), roof: mat(0x9c5140), sign: mat(0xf4e8c1),
  white: mat(0xf3edda), lamp: new THREE.MeshStandardMaterial({ color: 0xffe6a3, emissive: 0xffbd4d, emissiveIntensity: 1.25 }),
};
function box(parent, size, material, pos, cast = true) {
  const mesh = new THREE.Mesh(new THREE.BoxGeometry(...size), material); mesh.position.set(...pos); mesh.castShadow = cast; mesh.receiveShadow = true; parent.add(mesh); return mesh;
}
function cylinder(parent, radiusTop, radiusBottom, height, material, pos, rotation = [0,0,0], segments = 10) {
  const mesh = new THREE.Mesh(new THREE.CylinderGeometry(radiusTop, radiusBottom, height, segments), material);
  mesh.position.set(...pos); mesh.rotation.set(...rotation); mesh.castShadow = true; parent.add(mesh); return mesh;
}

// Road and verges
const ground = new THREE.Mesh(new THREE.PlaneGeometry(200, 1500), mats.grass); ground.rotation.x = -Math.PI / 2; ground.position.set(0, -.18, -520); ground.receiveShadow = true; scene.add(ground);
const road = new THREE.Mesh(new THREE.PlaneGeometry(14, 1500), mats.road); road.rotation.x = -Math.PI / 2; road.position.set(0, -.11, -520); road.receiveShadow = true; scene.add(road);
for (const x of [-7.25, 7.25]) { const verge = new THREE.Mesh(new THREE.PlaneGeometry(.5, 1500), mats.shoulder); verge.rotation.x = -Math.PI / 2; verge.position.set(x, -.1, -520); scene.add(verge); }
const lineObjects = [];
for (const x of [-2.32, 2.32]) for (let i = 0; i < 38; i++) {
  const dash = new THREE.Mesh(new THREE.BoxGeometry(.105, .018, 2.3), mats.line); dash.position.set(x, -.085, -i * 4.2); scene.add(dash); lineObjects.push({ mesh: dash, offset: i * 4.2 });
}
for (const x of [-6.65, 6.65]) { const edge = new THREE.Mesh(new THREE.BoxGeometry(.1,.018,1500), mats.line); edge.position.set(x,-.084,-520); scene.add(edge); }

// Player coach: vivid local intercity livery, detailed in simple geometry.
const bus = new THREE.Group(); scene.add(bus);
bus.position.set(0, 0, 0);
box(bus, [2.55, 2.8, 5.25], mats.busGreen, [0, 1.62, 0]);
box(bus, [2.58, .48, 5.28], mats.busRed, [0, .55, 0]);
box(bus, [2.58, .2, 5.28], mats.cream, [0, .85, 0]);
box(bus, [2.32, .24, 4.88], mats.busRed, [0, 2.83, .02]);
// Front windscreen and route sign
box(bus, [2.2, .83, .065], mats.black, [0, 2.05, -2.665]);
box(bus, [2.04, .68, .035], mats.glass, [0, 2.07, -2.705]);
box(bus, [1.32, .23, .06], mats.cream, [0, 2.61, -2.7]);
const routeCanvas = document.createElement('canvas'); routeCanvas.width = 512; routeCanvas.height = 96;
const ctx = routeCanvas.getContext('2d'); ctx.fillStyle = '#f1dfb2'; ctx.fillRect(0,0,512,96); ctx.fillStyle = '#254c3d'; ctx.font = 'bold 52px sans-serif'; ctx.textAlign = 'center'; ctx.fillText('ঢাকা  •  চট্টগ্রাম',256,66);
const routeTexture = new THREE.CanvasTexture(routeCanvas); routeTexture.colorSpace = THREE.SRGBColorSpace;
const routeSign = new THREE.Mesh(new THREE.PlaneGeometry(1.22,.19), new THREE.MeshBasicMaterial({ map: routeTexture })); routeSign.position.set(0,2.61,-2.738); bus.add(routeSign);
// Side passenger windows and red livery stripe
for (const side of [-1,1]) {
  for (let i=0;i<5;i++) {
    const z = -1.78 + i*.72;
    box(bus,[.045,.72,.57],mats.black,[side*1.285,2.12,z]);
    box(bus,[.025,.6,.47],mats.glass,[side*1.312,2.12,z]);
  }
  box(bus,[.04,.12,3.95],mats.cream,[side*1.3,1.36,0]);
  box(bus,[.045,.19,4.55],mats.busRed,[side*1.31,.91,0]);
  for (const z of [-1.65,1.65]) {
    const wheel = new THREE.Mesh(new THREE.CylinderGeometry(.56,.56,.25,16), mats.tire); wheel.rotation.z = Math.PI/2; wheel.position.set(side*1.3,.52,z); wheel.castShadow=true; bus.add(wheel);
    const hub = new THREE.Mesh(new THREE.CylinderGeometry(.25,.25,.27,12), mats.hub); hub.rotation.z=Math.PI/2; hub.position.set(side*1.31,.52,z); bus.add(hub);
  }
}
// Front grille, headlights, mirrors, bumper, roof vents
box(bus,[1.05,.34,.06],mats.black,[0,.77,-2.68]);
for(let i=0;i<5;i++) box(bus,[.07,.23,.025],mats.hub,[-.4+i*.2,.77,-2.72],false);
for(const x of [-.94,.94]) { box(bus,[.36,.24,.1],mats.lamp,[x,1.13,-2.69],false); box(bus,[.35,.11,.08],mats.white,[x,1.92,-2.69],false); }
box(bus,[2.68,.16,.15],mats.hub,[0,.34,-2.66]);
for(const side of [-1,1]) { box(bus,[.14,.11,.55],mats.black,[side*1.43,2.08,-1.92]); box(bus,[.18,.08,.32],mats.hub,[side*1.5,2.08,-2.15]); }
for(let i=0;i<3;i++) box(bus,[.42,.09,.38],mats.cream,[-.5+i*.5,2.99,.6],false);

// Handmade Bangladeshi roadside scenery.
const scenery = [];
function makeTree(x, offset, variant=0) {
  const g = new THREE.Group(); scene.add(g);
  const height = 2.8 + (variant%3)*.35;
  cylinder(g,.17,.28,height*.56,mats.trunk,[0,height*.28,0]);
  const crown = new THREE.Mesh(new THREE.IcosahedronGeometry(1.28 + (variant%2)*.22,1), variant%2?mats.leaf2:mats.tree);
  crown.position.set(0,height*.73,0); crown.scale.set(.92,1.1,.9); crown.castShadow=true; g.add(crown);
  scenery.push({group:g,x,offset,spacing:48}); return g;
}
function makeHut(x, offset) {
  const g=new THREE.Group(); scene.add(g);
  box(g,[2.3,1.25,1.7],mats.hut,[0,.72,0]);
  // pitched roof as two slanted panels
  const roofA=box(g,[1.4,.15,2.05],mats.roof,[-.52,1.52,0]); roofA.rotation.z=-.42;
  const roofB=box(g,[1.4,.15,2.05],mats.roof,[.52,1.52,0]); roofB.rotation.z=.42;
  box(g,[.52,.8,.06],mats.black,[0,.47,-.88],false);
  scenery.push({group:g,x,offset,spacing:144});
}
function makePalm(x, offset, idx) {
  const g=new THREE.Group(); scene.add(g);
  cylinder(g,.12,.19,3.2,mats.trunk,[0,1.6,0]);
  const crown=new THREE.Group(); crown.position.y=3.12; g.add(crown);
  for(let i=0;i<7;i++) { const leaf=new THREE.Mesh(new THREE.ConeGeometry(.22,2.15,5),mats.leaf2); leaf.position.y=-.35; leaf.rotation.z=Math.PI*.48; leaf.rotation.y=i*Math.PI*2/7; leaf.scale.set(.8,1,.48); leaf.castShadow=true; crown.add(leaf); }
  scenery.push({group:g,x,offset,spacing:78});
}
function makeSign(x, offset, text) {
  const g=new THREE.Group(); scene.add(g);
  cylinder(g,.055,.07,2.2,mats.trunk,[0,1.1,0]);
  box(g,[2.1,.7,.12],mats.sign,[0,2.1,0]);
  const c=document.createElement('canvas');c.width=512;c.height=160;const cctx=c.getContext('2d');cctx.fillStyle='#f4e8c1';cctx.fillRect(0,0,512,160);cctx.fillStyle='#245544';cctx.font='bold 58px sans-serif';cctx.textAlign='center';cctx.fillText(text,256,102);
  const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;
  const label=new THREE.Mesh(new THREE.PlaneGeometry(1.9,.59),new THREE.MeshBasicMaterial({map:tex}));label.position.set(0,2.1,.067);g.add(label);
  scenery.push({group:g,x,offset,spacing:220});
}
for(let i=0;i<34;i++) {
  const x = i%2 ? 9.2 : -9.2;
  makeTree(x, (i*19+13)%1550, i);
  if(i%4===0) makePalm(x+(x>0?1:-1), (i*47+76)%1550, i);
}
makeHut(-10.2,120); makeHut(10.2,340); makeHut(-10.2,650); makeHut(10.2,940);
makeSign(9.1,190,'কুমিল্লা'); makeSign(-9.1,560,'WELCOME'); makeSign(9.1,1000,'চট্টগ্রাম');

function createTraffic(index) {
  const group=new THREE.Group(); scene.add(group);
  const isVan=index%3===0, bodyMat=mat([0xf0d6a1,0x557c9a,0xd66a48,0xe6e1d1,0x3e735d][index%5],.56);
  const width=isVan?1.95:1.75, length=isVan?3.5:3.1;
  box(group,[width,1.1,length],bodyMat,[0,.85,0]);
  box(group,[width*.84,.55,.06],mats.glass,[0,1.04,-length*.5-.035]);
  box(group,[width*.82,.42,.055],mats.glass,[0,1.02,length*.5+.035]);
  for(const side of [-1,1]) for(const z of [-.75,.75]) {
    const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.29,.29,.15,10),mats.tire);wheel.rotation.z=Math.PI/2;wheel.position.set(side*width*.51,.32,z);group.add(wheel);
  }
  for(const x of [-.58,.58]) box(group,[.25,.13,.06],mats.lamp,[x,.61,-length*.5-.05],false);
